package cn.adc.shared.security;
import cn.adc.PgITSupport;import cn.adc.duration.*;import cn.adc.shared.audit.*;import cn.adc.shared.config.*;import cn.adc.shared.db.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.*;import javax.sql.DataSource;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="ADC_P0_IT_ENABLED",matches="true")
class StaffBindingAdapterIT {
 @Test void realDatabaseWriteUsesReloadedAuthorityAndDeniedAuditAfterRevocation()throws Exception {
  var stamp=new SourceStamp("SYNTHETIC-binding-source","v1","test-reviewer",Instant.EPOCH,true);var grant=new StaffAuthorization.Grant("v1",Set.of("HQ"),Set.of("DURATION_EDIT"),Set.of(),true);var entries=new AtomicReference<>(List.of(new StaffBindingAdapter.Entry("synthetic-hq",grant,stamp)));var binding=new StaffBindingAdapter(entries::get);var auth=new StaffAuthorization(()->Optional.of("synthetic-hq"),binding::bindings);var calls=new AtomicInteger();DataSource routing=(DataSource)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{DataSource.class},(p,m,a)->{if(m.getName().equals("getConnection")){if(calls.incrementAndGet()==2)entries.set(List.of());return PgITSupport.config().getConnection();}throw new UnsupportedOperationException();});var service=new DurationPolicyService(new JdbcTransactions(routing),auth,Clock.systemUTC());var r=service.create(UUID.randomUUID(),AuditDocuments.parse("{\"projectName\":\"SYNTHETIC revoked\",\"durationMinutes\":30}"));assertEquals("REJECTED",r.businessOutcome());assertNull(r.result());try(var c=PgITSupport.config().getConnection();var q=c.prepareStatement("SELECT authorization_context->>'decision',authorization_context->>'policyVersion' FROM adc.extension_operation_audit_event WHERE request_reference=? AND evidence->>'eventKind'='TERMINAL'")){q.setString(1,r.requestReference());try(var rows=q.executeQuery()){assertTrue(rows.next());assertEquals("DENY",rows.getString(1));assertEquals("UNBOUND",rows.getString(2));}}
 }
 @Test void readOnlyReferenceAdaptersRequireRealRowsAndExplicitSyntheticSource()throws Exception {
  var reader=new JdbcReferenceDataReader(PgITSupport.config());var stamp=new SourceStamp("SYNTHETIC-source","v1","test-reviewer",Instant.EPOCH,true);var clinic=new ClinicConfigurationAdapter(reader,()->List.of(new ClinicConfigurationAdapter.Entry(1,"SYNTHETIC-one","Asia/Tokyo",stamp)));assertEquals("Asia/Tokyo",clinic.find(1).zone().getId());assertThrows(ConfigurationUnavailable.class,()->clinic.find(2));var dentist=new DentistConfigurationAdapter(reader,()->List.of(new DentistConfigurationAdapter.Entry(1,Set.of(1L,2L),"SYNTHETIC-reviewed",true,stamp)));assertEquals(1,dentist.require(1,2).dentistId());assertThrows(ConfigurationUnavailable.class,()->dentist.require(9,1));
 }
}
